"""Starter resources for a synthetic IV numerical experiment; no target iteration."""
import numpy as np

def generate_data(rng, n, q=10, p=5, noise=1.0):
    Z = rng.multivariate_normal(np.zeros(q), np.eye(q), size=n)
    Theta = rng.multivariate_normal(np.zeros(p), np.eye(p), size=q)
    beta = rng.normal(0, 1, p)
    Phi = rng.multivariate_normal(np.zeros(p), np.eye(p), size=p)
    phi = rng.normal(0, 1, p)
    U = rng.multivariate_normal(np.zeros(p), np.eye(p), size=n)
    X = Z @ Theta + noise * (U @ Phi) + rng.multivariate_normal(np.zeros(p), np.eye(p), size=n)
    Y = X @ beta + noise * (U @ phi) + rng.normal(0, 1, n)
    return Y, X, Z, beta, Theta

def ols(A, B):
    """Least squares coefficients for A ~= B @ coef; no intercept."""
    return np.linalg.lstsq(B, A, rcond=None)[0]

def two_sls(Y, X, Z):
    theta_hat = ols(X, Z)
    X_hat = Z @ theta_hat
    return ols(Y, X_hat)
